 if(edit){$('view').oninput=e=>{const keep=e.target.dataset.layoutKeep,name=e.target.dataset.layoutName;if(keep!==undefined){layoutDraft.layouts.find(l=>l.id===Number(keep)).kept=e.target.checked;document.querySelector('.layout-count').textContent='已选 '+layoutDraft.layouts.filter(l=>l.kept).length+' 种布局';}if(name!==undefined)layoutDraft.layouts.find(l=>l.id===Number(name)).name=e.target.value;};}
