function previewOriginal(id,page=1){const t=item(id);if(!t?.sourceSlides)return;page=Math.max(1,Math.min(t.sourceSlides.length,page));const draft=layoutDraft?.id===id?layoutDraft:null,existing=draft?.layouts.find(l=>l.source===page);openDialog(`<button class="close" data-action="close" aria-label="关闭原PPT预览">×</button><h2 id="dialogTitle">原PPT预览 · ${esc(t.file)}</h2><p class="helper">直接展示原文件的实际页面，包含原有文字、图片与排版。关闭后可继续确认布局。</p><div class="large-template-preview"><img class="actual-template-preview" src="${esc(t.sourceSlides[page-1])}" alt="原PPT第${page}页"></div><div class="preview-footer"><button data-action="source-page" data-id="${id}" data-page="${page-1}" ${page===1?'disabled':''}>← 上一页</button><label class="source-page-selector">原PPT <select id="sourcePage" aria-label="跳转原PPT页码">${t.sourceSlides.map((_,i)=>`<option value="${i+1}" ${page===i+1?'selected':''}>第 ${i+1} 页</option>`).join('')}</select> / ${t.sourceSlides.length} 页</label><button data-action="source-page" data-id="${id}" data-page="${page+1}" ${page===t.sourceSlides.length?'disabled':''}>下一页 →</button></div>${draft?`<div class="source-add-row"><div><strong>${existing?.kept?'此页已在布局集中':'需要这个页面的样式？'}</strong><p class="helper">当前已选 ${draft.layouts.filter(l=>l.kept).length} 种布局，返回后可修改布局名称。</p></div><div><button data-action="close">返回布局确认</button><button class="primary" data-action="add-source-layout" data-id="${id}" data-page="${page}" ${existing?.kept?'disabled':''}>${existing?.kept?'已加入':existing?'重新保留此页':'＋ 将此页加入布局'}</button></div></div>`:''}`,'template-preview-dialog');$('sourcePage').onchange=e=>previewOriginal(id,Number(e.target.value));}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,id=button.dataset.id;
 if((a==='list'||a==='cancel-layout')&&layoutDraft&&JSON.stringify(layoutDraft.layouts)!==JSON.stringify(item(layoutDraft.id)?.layouts)){openDialog('<h2 id="dialogTitle">放弃本次布局调整？</h2><p>已确认的布局会保留，本次未保存的修改不会应用。</p><div class="dialog-actions"><button data-action="close" autofocus>继续调整</button><button class="danger" data-action="discard-layout">放弃调整</button></div>');return;}
 if(a==='discard-layout'){layoutDraft=null;$('dialog').close();location.hash='list';return;}
 if(a==='list'){location.hash='list';if(location.hash==='#list')render();}
 if(a==='upload')location.hash='upload';
 if(a==='view')location.hash='template/'+id;
 if(a==='filter'){filter=button.dataset.filter;renderList();}
 if(a==='clear'){filter='all';query='';renderList();}
 if(a==='supplement-layout')previewOriginal(id,1);
 if(a==='add-source-layout'){const t=item(id),page=Number(button.dataset.page);if(layoutDraft?.id!==id||!Number.isInteger(page)||page<1||page>t.sourceSlides?.length)return;const existing=layoutDraft.layouts.find(l=>l.source===page);if(existing){if(existing.kept)return;existing.kept=true;}else{const nextId=Math.max(-1,...layoutDraft.layouts.map(l=>l.id))+1;layoutDraft.layouts.push({id:nextId,name:'布局 '+(nextId+1),source:page,kept:true,manual:true,preview:t.sourceSlides[page-1]});}renderDetail(id,true);previewOriginal(id,page);toast('原PPT第 '+page+' 页已加入布局集');}
 if(a==='source-page')previewOriginal(id,Number(button.dataset.page));
 if(a==='preview-layout')previewLayout(id,Number(button.dataset.layout));
 if(a==='preview-previous'||a==='preview-next')previewLayout(id,Number(button.dataset.layout));
 if(a==='edit')editInfo(id);
 if(a==='close')$('dialog').close();
 if(a==='adjust'){layoutDraft=null;renderDetail(id,true);}
 if(a==='cancel-layout'){layoutDraft=null;location.hash='list';}
 if(a==='save-layout'){const kept=layoutDraft.layouts.filter(l=>l.kept);if(!kept.length||kept.some(l=>!l.name.trim())){$('layoutError').textContent=kept.length?'请填写保留布局的名称。':'请至少保留一种布局。';$('layoutError').scrollIntoView({block:'nearest'});return;}const t=item(id);t.layouts=structuredClone(layoutDraft.layouts);t.ready=true;t.date='2026-10-31';layoutDraft=null;filter='ready';query='';location.hash='list';toast('已确认 '+kept.length+' 种布局，模板可复用');}
 if(a==='delete'){const t=item(id);openDialog(`<h2 id="dialogTitle">删除这份模板？</h2><div class="delete-name">${esc(t.name)}</div><p>模板将从库中移除，之后不能再为新课件选择。</p><p>${t.uses?'这份模板已被复用 '+t.uses+' 次。':''}已生成的课件、历史版本和已保存的模板快照会保留。</p><div class="dialog-actions"><button data-action="close" autofocus>保留模板</button><button class="danger" data-action="confirm-delete" data-id="${id}">确认删除模板</button></div>`);}
 if(a==='confirm-delete'){templates=templates.filter(t=>t.id!==id);$('dialog').close();if(location.hash.startsWith('#template/'))location.hash='list';else renderList();toast('模板已删除');}
});
window.addEventListener('hashchange',render);render();
